/* This file is #included by gzip.c */

/*
 * pack(1) file format:
 *
 * The first 7 bytes is the header:
 *	00, 01 - Signature (US, RS), we already validated it earlier.
 *	02..05 - Uncompressed size
 *	    06 - Level for the huffman tree (<=24)
 *
 * pack(1) will then store symbols (leaf) nodes count in each huffman
 * tree levels, each level would consume 1 byte (See [1]).
 *
 * After the symbol count table, there is the symbol table, storing
 * symbols represented by corresponding leaf node.  EOB is not being
 * explicitly transmitted (not necessary anyway) in the symbol table.
 *
 * Compressed data goes after the symbol table.
 *
 * NOTES
 *
 * [1] If we count EOB into the symbols, that would mean that we will
 * have at most 256 symbols in the huffman tree.  pack(1) rejects empty
 * file and files that just repeats one character, which means that we
 * will have at least 2 symbols.  Therefore, pack(1) would reduce the
 * last level symbol count by 2 which makes it a number in
 * range [0..254], so all levels' symbol count would fit into 1 byte.
 */

import CMigration
import Darwin

let	PACK_HEADER_LENGTH = 7
let HTREE_MAXLEVEL = 24

/*
 * unpack descriptor
 *
 * Represent the huffman tree in a similar way that pack(1) would
 * store in a packed file.  We store all symbols in a linear table,
 * and store pointers to each level's first symbol.  In addition to
 * that, maintain two counts for each level: inner nodes count and
 * leaf nodes count.
 */
class unpack_descriptor_t {

  var gzip : gzip
  var symbol_size : UInt = 0		/* Size of the symbol table */
  var treelevels : Int = 0		/* Levels for the huffman tree */


  var symbolsin : [UInt] = []		/* Table of leaf symbols count in each level */
  var inodesin : [UInt] = [] 		/* Table of internal nodes count in each level */

  var readBuffer : ArraySlice<UInt8> = []
  var writeBuffer : Array<UInt8> = []
  
  var symbol : [UInt8] = []  // The symbol table
  var symbol_eob : Int = 0		/* Index of the EOB symbol */
  var tree : Array<Int> = []  // Decoding huffman tree (pointers to first symbol of each tree level

  var uncompressed_size : UInt = 0	/* Uncompressed size */
  var fpIn =  FileDescriptor.standardInput		/* Input stream */
  var fpOut = FileDescriptor.standardOutput		/* Output stream */

  // end of instance variables

  init(_ gzip: gzip) {
    self.gzip = gzip
  }
  /*
   * Release resource allocated to an unpack descriptor.
   *
   * Caller is responsible to make sure that all of these pointers are
   * initialized (in our case, they all point to valid memory block).
   * We don't zero out pointers here because nobody else would ever
   * reference the memory block without scrubbing them.
   */
  func descriptor_fini() {
    /*
     free(unpackd->symbolsin);
     free(unpackd->inodesin);
     free(unpackd->symbol);
     free(unpackd->tree);

     fclose(unpackd->fpIn);
     fclose(unpackd->fpOut);
     */
    flush()
  }

  /*
   * Recursively fill the internal node count table
   */
  func fill_inodesin(_ level : Int) {

    /*
     * The internal nodes would be 1/2 of total internal nodes and
     * leaf nodes in the next level.  For the last level there
     * would be no internal node by definition.
     */
    if level < treelevels {
      fill_inodesin(level + 1)
      inodesin[level] = (inodesin[level + 1] + symbolsin[level + 1]) / 2
    } else {
      inodesin[level] = 0
    }
  }

  /*
   * Read file header and construct the tree.  Also, prepare the buffered I/O
   * for decode routine.
   *
   * Return value is uncompressed size.
   */
  func parse_header(_ inx : FileDescriptor, _ out : FileDescriptor, _ pre : [UInt8]) -> UInt? {
    let hdr = UnsafeMutablePointer<UInt8>.allocate(capacity: PACK_HEADER_LENGTH)	/* buffer for header */
    //    ssize_t bytesread;		/* Bytes read from the file */
    //    int i, j, thisbyte;

    /* Prepend the header buffer if we already read some data */
    hdr.update(from: pre, count: pre.count)

    /* Read in and fill the rest bytes of header */
    guard let bytesread = try? inx.read(into: UnsafeMutableRawBufferPointer(start: hdr + pre.count, count: PACK_HEADER_LENGTH - pre.count)) else {
      gzip.maybe_err("Error reading pack header")
      return nil
    }
    gzip.r.infile_current += UInt(bytesread)

    var bytes_in = UInt(PACK_HEADER_LENGTH)

    /* Obtain uncompressed length (bytes 2,3,4,5) */
    uncompressed_size = 0;
    for i in 2 ... 5 {
      uncompressed_size <<= 8
      uncompressed_size |= UInt(hdr[i])
    }

    /* Get the levels of the tree */
    treelevels = Int(hdr[6])
    if treelevels > HTREE_MAXLEVEL || treelevels < 1 {
      gzip.maybe_errx("Huffman tree has insane levels")
    }

    /* Let libc take care for buffering from now on */
    fpIn = inx
    //    if ((fpIn = fdopen(in, "r")) == NULL) {
    //      maybe_err("Can not fdopen() input stream");
    //    }
    //    if ((fpOut = fdopen(out, "w")) == NULL) {
    //      gzip.maybe_err("Can not fdopen() output stream");
    //    }
    fpOut = out

    /* Allocate for the tables of bounds and the tree itself */
    inodesin =  Array(repeating: UInt(0), count: treelevels)
    symbolsin = Array(repeating: 0, count: treelevels)
    tree =      Array(repeating: 0, count: treelevels)

    /* We count from 0 so adjust to match array upper bound */
    treelevels -= 1

    /* Read the levels symbol count table and calculate total */
    symbol_size = 1;	/* EOB */
    for i in 0...treelevels {
      guard let thisbyte = fgetc() else {
        gzip.maybe_err("File appears to be truncated")
        return nil
      }
      symbolsin[i] = UInt(thisbyte)
      symbol_size += symbolsin[i];
    }
    bytes_in += UInt(treelevels)
    if symbol_size > 256 {
      gzip.maybe_errx("Bad symbol table")
    }
    gzip.r.infile_current += UInt(treelevels)

    /* Allocate for the symbol table, point symbol_eob at the beginning */
    symbol = Array(repeating: UInt8(0), count: Int(symbol_size))
    symbol_eob = 0

    /*
     * Read in the symbol table, which contain [2, 256] symbols.
     * In order to fit the count in one byte, pack(1) would offset
     * it by reducing 2 from the actual number from the last level.
     *
     * We adjust the last level's symbol count by 1 here, because
     * the EOB symbol is not being transmitted explicitly.  Another
     * adjustment would be done later afterward.
     */
    symbolsin[treelevels] += 1
    for i in 0...treelevels {
      tree[i] = symbol_eob
      for _ in 0 ..< symbolsin[i] {
        guard let thisbyte = fgetc() else {
          gzip.maybe_errx("Symbol table truncated")
          return nil
        }
        symbol[tree[i]] = thisbyte
        symbol_eob += 1
      }
      gzip.r.infile_current += symbolsin[i]
      bytes_in += symbolsin[i]
    }

    /* Now, take account for the EOB symbol as well */
    symbolsin[treelevels] += 1

    /*
     * The symbolsin table has been constructed now.
     * Calculate the internal nodes count table based on it.
     */
    fill_inodesin(0)
    return bytes_in
  }

  /*
   * Decode huffman stream, based on the huffman tree.
   */
  func decode(_ bytes_in : inout UInt) {
    //	int thislevel, thiscode, thisbyte, inlevelindex;
    //	int i;
    var bytes_out = 0
    /* The symbol pointer decoded from stream */

    /*
     * Decode huffman.  Fetch every bytes from the file, get it
     * into 'thiscode' bit-by-bit, then output the symbol we got
     * when one has been found.
     *
     * Assumption: sizeof(int) > ((max tree levels + 1) / 8).
     * bad things could happen if not.
     */
    var thislevel = 0;
    var thiscode = 0

    outer:
    while true {
      if let thisbyte = fgetc() {
        bytes_in += 1
        gzip.r.infile_current += 1
        gzip.check_siginfo();

        /*
         * Split one bit from thisbyte, from highest to lowest,
         * feed the bit into thiscode, until we got a symbol from
         * the tree.
         */
        for i in 0 ..< 8 {
          thiscode = (thiscode << 1) | ((Int(thisbyte) >> (7-i) ) & 1)

          /* Did we got a symbol? (referencing leaf node) */
          if (thiscode >= inodesin[thislevel]) {
            let inlevelindex = thiscode - Int(inodesin[thislevel])
            if inlevelindex > symbolsin[thislevel] {
              gzip.maybe_errx("File corrupt")
            }

            let thissymbol = symbol[tree[thislevel] + inlevelindex]
            // FIXME: did i get this right?
            if inlevelindex == 0 && bytes_out == uncompressed_size {
              break outer
            }

            fputc(thissymbol)
            bytes_out += 1

            /* Prepare for next input */
            thislevel = 0
            thiscode = 0
          } else {
            thislevel += 1
            if thislevel > treelevels {
              gzip.maybe_errx("File corrupt")
            }
          }
        }
      }
    }
  finished:
    if (bytes_out != uncompressed_size) {
      gzip.maybe_errx("Premature EOF")
    }
  }

  /* Handler for pack(1)'ed file */
  func unpack(_ iny : FileDescriptor, _ outy : FileDescriptor, _ pre : [UInt8]) -> (UInt, UInt)? {

    // FIXME: does dup'ing do anything
    guard let inx = try? iny.duplicate() else {
      gzip.maybe_err("dup")
      return nil
    }
    guard let out = try? outy.duplicate() else {
      gzip.maybe_err("dup")
      return nil
    }

// FIXME: the file descriptor instance variables should be set before calling parse_header
    guard var bytes_in = parse_header(inx, out, pre) else {
      return nil
    }
    decode(&bytes_in)
    descriptor_fini()

    /* If we reached here, the unpack was successful */
    return (uncompressed_size, bytes_in)
  }


  func fgetc() -> UInt8? {
    if !readBuffer.isEmpty {
      return readBuffer.removeFirst()
    }
    guard let bf = try? fpIn.readUpToCount(Int(BUFSIZ)), !bf.isEmpty else {
      return nil
    }
    readBuffer = ArraySlice(bf)
    return readBuffer.removeFirst()
  }

  func fputc(_ c : UInt8) {
    writeBuffer.append(c)
    if writeBuffer.count >= BUFSIZ {
      flush()
    }
  }

  func flush() {
    guard let _ = try? fpOut.write(writeBuffer) else {
      gzip.maybe_err("write")
      return
    }
    writeBuffer.removeAll(keepingCapacity: true)
  }
}
